"""Full CN translation from merged EN version."""
from docx import Document
cn = Document('四氧化三铁环氧树脂拟合/ESP-T_中文版.docx')
en = Document('四氧化三铁环氧树脂拟合/ESP-T_merged_1781620780.docx')

ref_start = None
for i,p in enumerate(en.paragraphs):
    if p.text.strip() == 'References': ref_start = i; break

def S(idx, text):
    if idx >= len(cn.paragraphs): return
    p = cn.paragraphs[idx]
    for r in p.runs: r.text = ''
    if len(p.runs) == 0: p.add_run('')
    p.runs[0].text = text

# Clear all CN body paragraphs first
for i in range(ref_start):
    if i < len(cn.paragraphs):
        for r in cn.paragraphs[i].runs: r.text = ''

# Title
S(0, "缓释型示踪支撑剂与基于传输的突破曲线解释用于压裂井产量监测")

# Abstract
S(2, "摘要：压裂非常规井的分段产量监测依赖示踪方法，然而解释缓释型示踪支撑剂的突破曲线以提取定量产量信息仍是一个未解决的挑战。本文建立了一个双分量传输模型，将突破曲线分解为高斯脉冲（关井积蓄段塞）和erfc拖尾（持续基质扩散控制释放），以平滑tanh权重函数连接。模型采用乳液聚合硬脂酸改性nano-Fe3O4@SA制备的亲油型环氧/Fe3O4缓释示踪支撑剂（ESP-T）进行验证。拟合单相驱替数据，模型R2 = 0.9939，恢复的有效产量流量Q与独立设定泵值误差在8%以内（0.46 vs. 0.50 mL/min）。erfc拖尾占总积分示踪信号的47%。ESP-T热稳定性达357 degC，水接触角104.6 deg（纯环氧72.3 deg），油过滤时间缩短66%。在稳态两相流条件下，示踪剂通量在4:1至1:4的油水比范围内追踪产油速率。该联合方法为无需井下仪器的分段产量监测提供了框架。")

# Keywords
S(4, "关键词：非常规油气藏；水力压裂；示踪支撑剂；环氧树脂；Fe3O4纳米颗粒；对流-弥散模型；分段建模；产量分配；释放动力学")

# Introduction
S(6, "1 引言")
S(7, "非常规油气资源——页岩油、致密油和煤层气——占全球剩余可采储量的一半以上[1-4]。其开发依赖水力压裂，通过高压流体在低渗透地层中构建人工裂缝，为烃类提供到达井筒的导流通道[5,6]。一口典型的水平井可沿其水平段压裂二十段或更多。")
S(9, "压裂后，各裂缝段对总产量的贡献差异显著，各段以不同速率递减[7]。作业者目前缺乏测量各段长期产油量的实用方法。生产测井需要井筒干预；分布式光纤传感成本高昂且仅限于新完井。一种仅从地面采样即可量化分段产量、无需井下工具的方法，将直接为重复压裂候选井筛选、加密钻井决策和后续井的压裂设计提供依据。")
S(11, "示踪方法提供了这一能力。每种压裂段加入化学特征互异的示踪剂，示踪剂出现于产出液中，其浓度历史携带着该段流量贡献的信息。缓释型示踪支撑剂[13-16]通过将示踪剂固定于随支撑剂共注入的固体载体中并逐步释放，将监测窗口从数小时延长至数周。然而，缓释型支撑剂产生了一个瞬时注入示踪剂所没有的解释难题。井口记录的突破曲线是两个重叠贡献的叠加：关井期间积蓄在支撑剂充填层中的示踪剂形成的浓度脉冲，和整个生产期间持续从载体基体中释放的示踪剂形成的缓慢衰减的长拖尾。仅靠观察曲线无法分离这两项贡献。当前实践采用经验的Korsmeyer-Peppas幂律模型描述释放[17,18]，它描述了示踪剂从载体中释放的量，但未提供解释井口信号的途径。基于ADE的拟合已被用于提取裂缝几何参数[19]；示踪剂质量平衡方法在不利用突破曲线形态的情况下进行产量分配[20]。一个将曲线分解为其分量贡献并从拟合参数中恢复产量速率的基于传输的框架，尚未得到充分关注[21-26]。")
S(13, "构建这样的框架需要两样东西：一个能够将复合突破曲线分解为物理意义明确的分量的传输模型，以及一个以基质扩散为主导释放机制——使持续拖尾充分发育——且表面亲油——使释放的示踪剂选择性分配进入油相——的示踪支撑剂。现有示踪支撑剂不能同时满足这两个要求。涂覆型支撑剂在涂层溶解后即失去示踪功能；聚苯乙烯微球缺乏约200 degC以上的热稳定性[27-30]。环氧树脂提供了有力的替代方案：其高度交联的网络提供了超过350 degC的热稳定性、耐化学性和可调控的力学性能[31,32]。乳液聚合将纳米粒子改性和示踪剂包覆整合于单步合成中。环氧包覆水溶性示踪剂已有报道[33,34]；用于油相监测的亲油型变体尚未见报道。")
S(17, "本文建立了一个传输模型，通过将缓释型示踪支撑剂的突破曲线分解为高斯脉冲（关井积蓄段塞）和erfc拖尾（持续基质扩散控制释放），以平滑tanh过渡连接，来解释该曲线。该分解从示踪信号中直接恢复有效产量流量Q。我们通过乳液聚合合成了亲油型环氧/Fe3O4缓释示踪支撑剂（ESP-T），以硬脂酸改性的nano-Fe3O4@SA为亲油示踪剂。我们表征了其微观结构、热稳定性、润湿性、油水传输选择性和力学完整性（第3.1-3.5节）；通过Korsmeyer-Peppas模型量化了其温度依赖性释放动力学（第3.6节）；应用传输模型从单相突破数据中恢复产量速率（第3.7节）；并将分析拓展至稳态油水两相流，使用示踪剂通量方法（第3.7节）。研究从材料设计出发，经释放表征，至传输建模和产量速率量化。")

# Methods
S(26, "实验所用化学试剂均为分析纯或工业级，未经进一步纯化直接使用。分析纯试剂包括乙醇（纯度>=99.7%）、氯化铁（FeCl3，纯度>=99.0%）、四水氯化亚铁（FeCl2.4H2O，纯度>=99.0%）、六水氯化锰（MnCl2.6H2O，纯度>=99.0%）、硬脂酸（纯度>=99.5%）和二氧化硅（SiO2，纯度>=99.99%），购自成都科龙化工有限公司。工业级试剂包括胍胶（纯度90%-95%）、E51环氧树脂（环氧值符合工业标准，纯度>=99%）、T31固化剂（有效成分含量95%）和中空玻璃微球（主成分纯度>=99%）。各材料详细规格见表2-1。")
S(31, "将配备氮气吹扫和机械搅拌的三口烧瓶置于恒温水浴中，加入100 mL去离子水加热至80 degC。达到目标温度后，加入2.703 g（0.01 mol）FeCl3，通氮气15 min，随后加入1.15 g（0.058 mol）FeCl2.4H2O和2x10-5 mol MnCl2.6H2O。搅拌10 min后，迅速加入5.5 mL氨水，在pH 10条件下反应2 h。反应结束后，将黑色悬浮液转移至锥形瓶，磁分离弃去上清液。沉淀用无水乙醇超声反复洗涤至中性pH后收集。最后，将沉淀与硬脂酸乙醇溶液混合，超声进行亲油改性，冲洗后定容至100 mL保存[21]。")
S(36, "将0.3 g 20 nm SiO2加入150 mL去离子水中，380 RPM搅拌制备SiO2水分散液。另称取0.9 g胍胶和0.5 g 45 um SiO2备用。将20 mL E51环氧树脂、6 g Fe3O4-乙醇混合液、1 g中空玻璃微球和7 g T31固化剂手动搅拌3 min预混。将预混液转移至SiO2分散液中搅拌1 min完成乳化，随后加入45 um SiO2和胍胶稳定体系。微球成型后，于50 degC固化1 h，去离子水冲洗，80 degC干燥10 h即得ESP-T。纯环氧微球的制备以6 g纯乙醇替代Fe3O4-乙醇混合液。")
S(42, "采用扫描电子显微镜（SEM，ZEISS-Sigma 500）分析纯环氧微球和ESP-T的微观结构、元素组成及分布。样品在真空下溅射镀导电金属膜，粘贴于导电胶带上，在低倍至50,000倍放大范围内观察。通过场发射电子枪激发特征X射线，在选定区域进行二维元素面扫描成像，观察Fe元素在支撑剂中的分布。")
S(44, "采用光学显微镜（Leica DM2700P）观察两种支撑剂的表面形貌和颗粒分散性。热重分析（TGA，TA Instruments Q500，美国）在空气气氛中以10 degC/min升温速率、50-800 degC温度范围测试两种支撑剂的热稳定性。")
S(46, "水接触角（WCA）测量使用视频光学接触角分析仪（OCA20，德国）。将压制支撑剂薄片置于测试台，滴加5 uL去离子水于样品表面，液滴稳定后采集图像，每个样品进行五次平行测量。")
S(48, "通过圆度、球度、体积密度、视密度、酸溶解度和破碎率综合评估支撑剂的物理力学性能及现场适用性。油水导流能力通过过滤时间间接评价：将2.0 g支撑剂加入底部以200目筛网封堵的漏斗中，加入20 mL去离子水或十二烷，记录完全渗透所需时间。")
S(50, "将ESP-T（5 g，40-70目）加入含100 mL十二烷的玻璃瓶中。密封瓶置于30、60、90和120 degC的恒温油浴中。每12 h取样，采用电感耦合等离子体质谱（ICP-MS，PerkinElmer NexION 300X）测定十二烷中示踪金属离子浓度，绘制释放曲线。")
S(55, "单相产量监测以十二烷为模型油，在动态驱替装置中模拟（图2-4）。将ESP-T填充至钢管岩心（直径2.5 cm，长度5.0 cm），两端以200目筛网密封以防支撑剂迁移。将岩心置于岩心夹持器中，施加5 MPa围压。以5 mL/min注入十二烷至管柱完全饱和，关闭出口阀，静置96 h使示踪剂在支撑剂充填层油相中积蓄。随后以0.5 mL/min注入十二烷模拟生产。每4 min采集流出液样品（2 mL），共20组，采用ICP-MS测定标记元素浓度。")
S(60, "两相实验将体系维持在稳态流动状态，无闷井期，模拟油井连续生产。以控制速率共注入十二烷和水，实现三种油水体积比（OWR = 4:1、1:1、1:4）和四种总流量（0.1、0.2、0.3、0.4 mL/min），覆盖从油主导到水主导的生产范围（图2-5）。含支撑剂的岩心置于5 MPa围压下。每5 min采集流出液样品（2 mL），共20组，记录油水体积比，采用ICP-MS定量示踪金属浓度。")

# Results 3.1-3.6
S(67, "ESP-T微球形态良好且高度均匀。低倍SEM成像（图3-1，面板a和d）显示纯环氧和ESP-T样品均具有优异的球形度，无颗粒间团聚，证实乳液聚合工艺能够容纳nano-Fe3O4@SA填料而不受干扰。最直观的差异在纹理上：纯环氧表面光滑，偶有颗粒碎屑；而ESP-T表面均匀粗糙，这是纳米填料已被掺入整个颗粒的初步迹象。")
S(69, "在更高放大倍数下差异更加明显。纯环氧微球（面板b）呈现细微的褶皱和浅凹陷，是热固性树脂固化收缩的产物。ESP-T（面板e）则呈现出截然不同的形态：表面密集覆盖着微米和亚微米尺度的凸起，以离散岛状而非聚结团块分布。这一形貌表明nano-Fe3O4@SA以纳米团簇形式分散于环氧基体中，硬脂酸改性成功防止了否则会产生大块团聚体的不可控宏观相分离。")
S(71, "最高放大倍数图像（面板c和f）揭示了纳米填料与基体的相互作用方式。纯环氧呈现出交联聚合物网络预期的致密、起伏的熔岩状纹理。ESP-T显示出碎屑状表面形貌，可以辨别出被硬脂酸包裹的单个纳米团簇。关键的界面特征是这些纳米团簇与底层环氧之间没有裂缝或间隙。它们呈现嵌入状态而非简单附着。这种紧密结合是直接的结构证据，表明硬脂酸的长烷基链与环氧链形成了物理缠结和疏水相互作用，产生了耐用复合支撑剂所需的牢固界面粘合。")
S(73, "综合来看，这些图像提示了以下形成路径：疏水改性的nano-Fe3O4@SA纳米团簇均匀分散于乳化后的环氧液滴中，随着聚合物网络交联而被固定。在固化收缩过程中，部分团簇被挤出至颗粒表面，产生面板c和f中可见的表面富集粗糙纳米结构。需要指出，该机制基于固化后显微观察推断，实时原位表征才能直接确认动力学路径。")
S(78, "EDS元素面扫描（图3-2）确认了形貌所提示的信息。Fe信号遍布整个颗粒截面，证明nano-Fe3O4@SA位于环氧基体内部而非仅装饰表面。信号强度中轻微的不均匀性指向复合物内不同的相域，与SEM中观察到的纳米团簇分散一致。成像和元素数据共同确立了所设计的ESP-T结构已成功实现。")
S(83, "热分析（图3-3）识别出三个分解阶段。第一阶段50-350 degC，失重5.70%，归因于吸附水和残余乙醇。第二阶段350-400 degC为主要分解：环氧网络中C-O-C和C-C键的断裂释放CO2和小分子烃类，DTG曲线在357.27 degC达到峰值，占总失重的72.5%。400 degC以上残余质量趋于稳定，进一步失重来自碳质残渣的氧化燃烧。最终残渣包含中空玻璃微球、热稳定的nano-Fe3O4@SA和少量碳质组分。伴随分解的DSC吸热峰与DTG谱一致。")
S(87, "357.27 degC的初始分解温度远高于油气井的温度范围（通常80-150 degC，深井可达200 degC）。200 degC以下仅失去微量水分，环氧基体无任何可检测的降解。这一热裕度表明环氧基体在油气井全作业温度范围内可保持结构完整性。")
S(92, "SEM记录的形貌变化对应于表面润湿性的显著转变。水接触角测量（图3-4）显示纯环氧微球平均为72.3 deg，与环氧链上存在的羟基一致。ESP-T为104.6 deg，提升了32.3 deg，跨越了疏水阈值。这一转变由硬脂酸改性驱动：羧基与Fe3O4表面羟基配位，而C17烷基链朝外定向排列，形成低能疏水膜。SEM记录的纳米团簇挤出驱动的表面富集效应放大了这一效果。")
S(99, "两种支撑剂均比水轻。纯环氧微球体积密度为0.6179 g/cm3，视密度为1.02 g/cm3（图3-5）；ESP-T分别为0.646和1.072 g/cm3。升高反映了nano-Fe3O4@SA（约5.18 g/cm3）相对于环氧（约1.1 g/cm3）的更高密度。两个值均低于水的密度，意味着支撑剂可在水基压裂液中悬浮而无需额外添加剂。视密度增加0.05 g/cm3与纳米团簇填充内部孔隙一致，产生了更致密的颗粒结构。")
S(105, "过滤测试（图3-6，表3-1）量化了润湿性反转的传输后果：水通过纯环氧充填层不到三分钟，但在相同条件下渗透ESP-T充填层需要近半小时。对十二烷则相反：纯环氧通过油需15分钟以上，ESP-T仅需5分钟，缩短66%。疏水表面排斥水进入粒间孔隙，同时允许油自由铺展。在同时产出两相的地层中，这种选择性有利于油流向井筒同时抑制水突破。")
S(108, "（a,b）纯环氧水通过前后；（c,d）纯环氧油通过前后；（e,f）ESP-T水通过前后；（g,h）ESP-T油通过前后。")
S(113, "储层温度随深度增加而升高，由于示踪剂从环氧基体中的释放是扩散控制过程，温度直接影响释放速率。图3-7(a)显示了ESP-T在十二烷中于30、60、90和120 degC下的释放曲线，以归一化浓度C/C0对时间作图。释放随温度在所有时间点均加速。释放速率在流体接触的最初24小时内最高，随后逐渐衰减（图3-7c）。在120 degC下，14天累积释放仍远高于ICP-MS检测阈值，确认ESP-T可在长期监测相关的时间尺度上维持可测量的示踪信号。")
S(122, "Korsmeyer-Peppas（K-P）模型C/C0 = K tn [23]通过扩散指数n区分释放机制。对球形载体：n <= 0.43为Fick扩散控制释放，0.43 < n < 0.85为两种机制共同控制的非Fick异常传输，n >= 0.85为Case-II松弛控制释放[24]。")
S(124, "K-P模型拟合至各温度下的释放数据（图3-7b，表3-2）。速率常数K从30 degC的0.055系统性增至120 degC的0.196，与扩散和聚合物松弛均受热激活的本质一致。所有拟合n值均落在0.45-0.85范围内，对应于非Fick异常传输。各温度下R2均超过0.94。K-P模型作为幂律形式缺乏上渐近线，严格适用于Mt/Minf < 0.6；报告的R2值适用于0-14天拟合范围。")
S(126, "这些结果与溶剂驱动的溶胀机制一致。十二烷分子渗透进入交联环氧网络，产生由内部玻璃核和外部凝胶层构成的双层结构。溶胀降低了聚合物链缠结，形成了示踪剂扩散至外部介质的扩展传输通道。更高温度增强了溶剂渗透性，加速了溶胀，削弱了网络内分子间作用力，扩大了可供示踪剂扩散的孔隙尺寸。")

# Section 3.7
S(134, "缓释型支撑剂的突破曲线包含两个重叠信号：关井期间积蓄的示踪剂形成的段塞，和持续释放的示踪剂形成的拖尾。由于重叠，两者均无法仅靠观察分离。\n\n我们采用一维对流-弥散方程分离它们：dC/dt + v dC/dx = D d2C/dx2，其中v = 4Q/(pi d2)将模型与产量速率Q连接，D = alpha v反映混合。关井段塞由瞬时注入解[25]（高斯脉冲）描述。持续释放由连续源解（erfc函数）描述。两者通过tanh权重w(t) = 1/2 [1 + tanh((t0-t)/sigma)]拼接，产生平滑过渡。模型C(t) = cb + w(t) C_rise + [1-w(t)] C_fall为式（2）。sigma固定为采样间隔（4 min）。\n\nQ之所以能被恢复，是因为v同时出现在两个分量中：它决定脉冲的到达时间和宽度，以及拖尾的衰减速率。作为两个分量共享的唯一参数，Q被数据的两个独立部分联合约束。模型未被告知泵速；它从曲线形态中恢复了Q。")
S(148, "拟合单相突破曲线（图3-8b，表3-3），模型R2 = 0.9939，RMSE = 0.0210。Q = 0.46 mL/min与泵设0.50 mL/min误差在8%以内。MRT = 37.4 min与x/v = 38.6 min匹配。Pe = x/alpha = 0.934与渐进释放源一致。积分分量显示47%的信号源于erfc拖尾。")
S(152, "Q、MRT和Pe各自与独立已知值一致，表明模型恢复的是物理量而非过拟合。47%的拖尾贡献意味着无需反复关井信号即可持续。尾端平台浓度cb反映稳态释放通量；由于ESP-T释放为热激活（K从0.055升至0.196，30-120 degC），cb应随储层温度缩放。\n\n这与先前基于ADE的示踪分析不同，后者提取裂缝几何[19]、执行质量平衡分配[20]或表征裂缝网络[26]。本文的传输分解本身即产出产量指标。")
S(154, "为检验模型在两相条件下的表现，我们在OWR = 4:1、1:1、1:4和0.1-0.4 mL/min下进行了稳态驱替。OWR = 1:1时早期流出液油相分数更高，与ESP-T的亲油特性一致（第3.5节）。")
S(156, "图3-9(a)：浓度随总流量增加而降低（稀释效应），与OWR无关。浓度本身混淆了释放速率和稀释。")
S(158, "因此定义示踪剂通量FO =（油相浓度）x（油相流量），即单位时间的示踪剂质量。FO等于ESP-T释放速率[8]，不受稀释影响。图3-9(b)：FO随OWR增大而升高，但在恒定OWR下随流量变化保持恒定，与油润湿面积控制释放一致。")
S(160, "图3-9(c)以单相稳态值（3.187 ug/min）归一化FO。归一化FO与各OWR下已知油相流量吻合，确认产油速率可从FO中恢复。边界：单段假设、稳态标定、十二烷为模型油、120 degC以上或腐蚀性流体中长期稳定性未测试。")

# Conclusions
S(170, "建立了一个双分量传输模型，通过将缓释型示踪支撑剂的突破曲线分解为高斯脉冲和erfc拖尾来解释曲线。合成了亲油型环氧/Fe3O4支撑剂（ESP-T），在关井后单相流和稳态两相流中进行了验证。")
S(172, "模型恢复产量流量Q与已知泵设值误差在8%以内。erfc拖尾占总信号的47%，确认持续释放从单次关井即可提供持久监测信号。拟合参数与独立实验值内部一致。")
S(174, "ESP-T提供357 degC的热稳定性、亲油表面（WCA 104.6 deg，油过滤缩短66%）和自悬浮能力（体积密度0.646 g/cm3）。示踪剂通量在4:1至1:4的油水比范围内追踪产油速率。")
S(176, "验证限于实验室单段实验，使用十二烷。现场应用需要以原油在多段、多相条件下测试。本文建立了解释框架和实验技术基础。")

